var s={slug:"smart-light",title:"Mission: The Smart Light",subtitle:"Sense the light. Make the right decision.",summary:"Explore a 3D dusk-to-dawn lamp, identify its parts, and program it to stay on overnight and switch off at dawn. Connect the idea to a micro:bit and NeoPixel classroom build.",badge:"GLOW",color:"#22b8cf",activity:"smart-light",activityLabel:"Keep the garden lit overnight",activityInstruction:"Choose the lamp action for darkness and daylight. Test your rule at dusk, at night and at dawn. Pass all three scenes.",exploreTitle:"What happens from dusk to dawn?",exploreInstruction:"Choose Day, Dusk, Night or Dawn. Change the light reading and threshold. Watch the 3D lamp respond automatically.",difficulty:1,topics:["Light sensing","Inputs and outputs","Conditions","NeoPixel","Saving electricity"],classIds:["Microbit"],storyVideoUrl:"https://www.youtube.com/embed/4WOeBSl4Yl8",warmupVideoUrl:"",storyQuestions:[{prompt:"How was the classroom in the morning?",answers:["Dark","Very bright","Full of smoke"],correctIndex:0,success:"The classroom was dark in the morning."},{prompt:"What did the teacher do?",answers:["Opened a window","Turned on the light","Left the room"],correctIndex:1,success:"The teacher turned on the light."},{prompt:"What happened later?",answers:["It started to rain","The bell rang","The sun came out"],correctIndex:2,success:"Later, the sun came out."},{prompt:"Was the classroom still dark?",answers:["No. It was bright","Yes. It stayed dark","It was dark again at noon"],correctIndex:0,success:"No, the classroom was bright."},{prompt:"Was the light still on?",answers:["No, it was off","Only one lamp","Yes"],correctIndex:2,success:"Yes, the light was still on."},{prompt:"What did the children forget to do?",answers:["Turn off the light","Close the door","Tidy the table"],correctIndex:0,success:"They forgot to turn off the light."},{prompt:"Did the same thing happen again?",answers:["No, never again","Yes","Only once"],correctIndex:1,success:"Yes, the same thing happened again."}],parts:[{id:"housing",label:"Lamp housing",fact:"The housing protects the light and the parts inside. This outdoor lamp is a real-world example of automatic lighting.",help:"Turn the lamp and tap its dark outer body or mounting bracket."},{id:"photocell",label:"Light sensor",fact:"The light sensor detects how bright or dark it is outside. In our classroom build, the micro:bit senses the light.",help:"Find the small blue sensor on top of the lamp."},{id:"led-lamp",label:"LED light",fact:"The LEDs give us light when it gets dark. The sensor helps the lamp turn off again when daylight returns.",help:"Tap the round light at the front of the lamp."}],quiz:[{prompt:"Which reading means less light?",answers:["20","220","255"],correctIndex:0,success:"A lower light reading means a darker environment."},{prompt:"Which part runs the program?",answers:["The wire alone","The micro:bit","The table"],correctIndex:1,success:"The micro:bit reads the input and controls the output."},{prompt:"What are the NeoPixels in this system?",answers:["The light sensor","A temperature reading","The light output"],correctIndex:2,success:"NeoPixels produce the light we control."},{prompt:"With a threshold of 128, what should a reading of 40 do?",answers:["Turn the light on","Turn the light off","Change the pin"],correctIndex:0,success:"40 is below 128, so our automatic light turns on."},{prompt:"With a threshold of 128, what happens at exactly 128?",answers:["The light must flash","The light is off","The sensor stops working"],correctIndex:1,success:"Our rule uses less than 128 for on. At 128 or above, it turns off."},{prompt:"Why turn the light off when it is already bright?",answers:["To make more noise","To hide the sensor","To avoid using light unnecessarily"],correctIndex:2,success:"Switching off when light is not needed can save electricity."}]};export{s as a};
